// Floyd 判圈：把 i → nums[i] 看成鏈結串列，重複數就是環的入口
// 時間複雜度: O(n)，空間複雜度: O(1)
function findDuplicate(nums) {
    let slow = nums[0], fast = nums[nums[0]];
    while (slow !== fast) {
        slow = nums[slow];
        fast = nums[nums[fast]];
    }
    slow = 0; // 一個從起點出發，一個從相遇點出發
    while (slow !== fast) {
        slow = nums[slow];
        fast = nums[fast];
    }
    return slow;
}

